+	} else {
+		logger.Info("KNIRVORACLE: using env var", zap.String("url", knirvOracledRPCURL))
 	}

 	// Initialize NRN integration
 	nrnIntegration := economics.NewNRNIntegration(knirvOracledRPCURL, nrvSystem)

